package org.example

import java.io.File
import kotlin.test.assertTrue
import kotlin.test.Test
import org.gradle.testkit.runner.GradleRunner
import org.junit.jupiter.api.io.TempDir

/**
 * A simple functional test for the 'org.example.greeting' plugin.
 */
class VlcjBundlerGradlePluginPluginFunctionalTest {
    @TempDir
    lateinit var testProjectDir: File

    private val buildFile by lazy { testProjectDir.resolve("build.gradle.kts") }
    private val settingsFile by lazy { testProjectDir.resolve("settings.gradle.kts") }

    @Test
    fun `can run downloadVlcNatives task successfully`() {
        // Set up the dummy test project structure
        settingsFile.writeText("rootProject.name = \"vlc-test-sandbox\"")

        buildFile.writeText("""
            plugins {
                kotlin("jvm") version "2.3.0"
                id("org.jetbrains.kotlin.plugin.compose") version "2.3.0"
                id("org.jetbrains.compose") version "1.10.3"
                id("dev.krtirtho.vlcj-bundler.gradle-plugin")
            }
            
            repositories {
                mavenCentral()
                google()
            }
            
            compose.desktop {
                application {
                    mainClass = "MainKt"
                }
            }
        """.trimIndent())

        // Run the custom task using GradleRunner
        val result = GradleRunner.create()
            .withProjectDir(testProjectDir)
            .withArguments("downloadVlcNatives", "--stacktrace")
            .withPluginClasspath() // Automatically injects your plugin code
            .build()

        // Assert that the task executed successfully
        assertTrue(result.output.contains("Windows streaming audio binaries successfully filtered") ||
                result.output.contains("Automatic extraction of Mac DMG files"))

        // Assert that the build folder sandbox was created
        val vlcNativesDir = File(testProjectDir, "build/vlc-natives")
        assertTrue(vlcNativesDir.exists(), "The plugin should create a vlc-natives folder inside build/")
    }
}
